class ReadOnlySchema(typing.Mapping[str, typing.Any]):
    """A Mapping that is deliberately not a dict."""

    def __init__(self, data: dict[str, typing.Any]) -> None:
        self.data = data

    def __getitem__(self, name: str) -> typing.Any:
        return self.data[name]

    def __iter__(self) -> typing.Iterator[str]:
        return iter(self.data)

    def __len__(self) -> int:
        return len(self.data)


def scripted_server(text: str) -> ScriptedHTTPServer:
    body = openai_success_response(text=text)
    routes = {
        ("POST", CHAT_PATH): [
            ScriptedResponse(
                status_code=200,
                headers={"Content-Type": "application/json"},
                body=body,
            )
        ]
    }
    return ScriptedHTTPServer(port=0, routes=routes)


